    h, w = len(grid), len(grid[0])
    # Find vertical marker columns: columns containing a contiguous run of
    # at least two nonzero cells below the horizontal pattern area.
    marker_cols = set()
    for c in range(w):
        run = 0
        for r in range(h - 1, -1, -1):
            if grid[r][c]:
                run += 1
                if run >= 2:
                    marker_cols.add(c)
            else:
                run = 0
    for c in marker_cols:
        sources = []
        for r in range(h):
            if grid[r][c] != 0:
                continue
            left = grid[r][c - 1] if c > 0 else 0
            right = grid[r][c + 1] if c + 1 < w else 0
            if left and left == right:
                sources.append((r, left))
        # Each horizontal gap's color propagates upward until the preceding
        # horizontal source; the highest source propagates to the top edge.
        for i, (r, color) in enumerate(sources):
            upper = sources[i - 1][0] + 1 if i else 0
            for rr in range(upper, r + 1):
                if out[rr][c] == 0:
                    out[rr][c] = color
    return out
